private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Retrieve the first byte and mask to unsigned
    int b0;
    try {
        b0 = bb.get(i) & 0xFF;
    } catch (IndexOutOfBoundsException e) {
        // No bytes left; insert replacement character
        sb.append('\uFFFD');
        return i;
    }

    // ASCII
    if (b0 < 0x80) {
        sb.append((char) b0);
        return i + 1;
    }

    // Invalid leading byte
    if (b0 < 0xC0) { // continuation byte in a wrong place
        sb.append('\uFFFD');
        return i + 1;
    }

    // 2-byte sequence
    if (b0 < 0xE0) {
        try {
            int b1 = bb.get(i + 1) & 0xFF;
            if ((b1 & 0xC0) != 0x80) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int cp = ((b0 & 0x1F) << 6) | (b1 & 0x3F);
            sb.append((char) cp);
        } catch (IndexOutOfBoundsException e) {
            sb.append('\uFFFD');
        }
        return i + 2;
    }

    // 3-byte sequence
    if (b0 < 0xF0) {
        try {
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80)) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int cp = ((b0 & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
            sb.append((char) cp);
        } catch (IndexOutOfBoundsException e) {
            sb.append('\uFFFD');
        }
        return i + 3;
    }

    // 4-byte sequence
    if (b0 < 0xF8) {
        try {
            int b1 = bb.get(i + 1) & 0xFF;
            int b2 = bb.get(i + 2) & 0xFF;
            int b3 = bb.get(i + 3) & 0xFF;
            if (((b1 & 0xC0) != 0x80) || ((b2 & 0xC0) != 0x80) || ((b3 & 0xC0) != 0x80)) {
                sb.append('\uFFFD');
                return i + 1;
            }
            int cp = ((b0 & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
            if (cp < 0x10000 || cp > 0x10FFFF) {
                sb.append('\uFFFD');
            } else {
                int high = 0xD800 + ((cp - 0x10000) >> 10);
                int low = 0xDC00 + ((cp - 0x10000) & 0x3FF);
                sb.append((char) high);
                sb.append((char) low);
            }
        } catch (IndexOutOfBoundsException e) {
            sb.append('\uFFFD');
        }
        return i + 4;
    }

    // Bytes 0xF8-0xFF (invalid in standard UTF‑8)
    sb.append('\uFFFD');
    return i + 1;
}

int visitFrameStart(final int offset, final int numLocal, final int numStack) {
    if (offset < 0) {
        throw new IllegalArgumentException("offset cannot be negative");
    }
    if (numLocal < 0) {
        throw new IllegalArgumentException("numLocal cannot be negative");
    }
    if (numStack < 0) {
        throw new IllegalArgumentException("numStack cannot be negative");
    }
    try {
        // Allocate a new frame: offset + numLocal + numStack + placeholder area for frame contents
        // Use an int[] for simplicity: first element offset, second numLocal, third numStack
        this.currentFrame = new int[3 + numLocal + numStack];
        int index = 0;
        currentFrame[index++] = offset;   // store offset
        currentFrame[index++] = numLocal; // store number of locals
        currentFrame[index++] = numStack; // store number of stack items
        // After storing the header, the next writing position is 'index'
        return index;
    } catch (Exception ex) {
        // wrap any runtime exception in a RuntimeException to preserve stack trace
        throw new RuntimeException("Unable to start a new frame", ex);
    }
}

