private TreeNode<T> rotateRight(TreeNode<T> node){
    try {
        if (node == null) return null;
        // No rotation possible if left child is absent
        if (node.left == null) return node;
        // Perform right rotation
        TreeNode<T> leftChild = node.left;
        node.left = leftChild.right;
        leftChild.right = node;
        return leftChild;
    } catch (Exception e) {
        // In case of unexpected runtime issues, return the original node
        return node;
    }
}

@SuppressWarnings("unchecked") public static void addToClassPath(Vector<URL> cpV,String dir){
    // 1. Validate inputs
    if (cpV == null || dir == null) {
        return;
    }

    // 2. Resolve the directory
    File dirFile = new File(dir);
    if (!dirFile.isDirectory()) {
        return;
    }

    // 3. Get all .jar files (case‑insensitive)
    File[] jars = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File d, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });

    if (jars == null || jars.length == 0) {
        return;
    }

    // 4. Convert each jar to a URL and add it to the vector
    for (File jar : jars) {
        try {
            URL url = jar.toURI().toURL();
            cpV.add(url);
        } catch (MalformedURLException e) {
            // Skip this jar if the URL is malformed
            continue;
        }
    }
}

