private int parseEndOfLine(String headerPart,int end){
    if (headerPart == null){
        throw new IllegalArgumentException("headerPart cannot be null");
    }
    if (end < 0 || end >= headerPart.length()){
        throw new IllegalArgumentException("Invalid starting index: "+end+" for header of length "+headerPart.length());
    }
    int len = headerPart.length();
    for (int i = end; i < len - 1; i++){
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i; // index of the start of the CRLF sequence
        }
    }
    throw new IllegalArgumentException(
        "No end-of-line sequence (\\r\\n) found in headerPart starting at index " + end);
}

