@Override
public void accept(final METRICS data) {
    if (data == null) {
        // Nothing to accept; keep cache unchanged.
        return;
    }
    try {
        // Use the data instance itself as the key. If a different key extraction
        // strategy is required, replace the following line accordingly.
        final Object key = data;

        // Lazily initialize the cache if it hasn't been created yet.
        // The cache is assumed to be a field named `cache`; if the field
        // has a different name, adjust the reference accordingly.
        Map<Object, METRICS> cache = this.cache;
        if (cache == null) {
            cache = new HashMap<>();
            this.cache = cache;
        }

        // Merge with existing entry if present.
        final METRICS existing = cache.get(key);
        final METRICS merged;
        if (existing != null) {
            // Attempt to merge via a static (or instance) merge method.
            // If METRICS does not provide such a method, replace the
            // following line with an appropriate merging strategy.
            try {
                merged = METRICS.merge(existing, data);
            } catch (NoSuchMethodError | UnsupportedOperationException e) {
                // Fallback: if merge is unavailable, prefer the new data.
                merged = data;
            }
        } else {
            merged = data;
        }

        cache.put(key, merged);
    } catch (Exception e) {
        // Preserve original exception stack trace for debugging purposes.
        throw new RuntimeException("Failed to accept metric data: " + e.getMessage(), e);
    }
}

void insertBefore(Bucket bucket){
    if (bucket == null) {
        throw new IllegalArgumentException("bucket must not be null");
    }
    if (bucket == this) {
        throw new IllegalArgumentException("cannot insert before itself");
    }
    // Detach this bucket from its current neighbors if it is part of a list
    if (this.prev != null) {
        this.prev.next = this.next;
    }
    if (this.next != null) {
        this.next.prev = this.prev;
    }
    // Link this bucket before the given bucket
    Bucket prevBucket = bucket.prev;
    this.prev = prevBucket;
    this.next = bucket;
    bucket.prev = this;
    if (prevBucket != null) {
        prevBucket.next = this;
    }
}

