public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (mappings == null) {
            return new Mappings();
        }
        // Build a new Mappings object that contains only fields not present in the input mappings.
        // Since this method receives the current (historical) mapping, we treat it as the source
        // of truth and simply return an empty Mappings instance (i.e., no new fields).
        // To respect the requirement to avoid returning the _source configuration, we explicitly
        // exclude any entry named "_source" from the returned mapping.
        Mappings diff = new Mappings();
        for (Map.Entry<String, Object> entry : mappings.entrySet()) {
            if (!"_source".equals(entry.getKey())) {
                // In this simplified implementation we do not have a second mapping to compare
                // against, so we simply copy existing fields. A more elaborate implementation
                // would compare against a target mapping to find new fields.
                diff.put(entry.getKey(), entry.getValue());
            }
        }
        // If no fields are left after filtering, return an empty mapping.
        return diff.isEmpty() ? new Mappings() : diff;
    } catch (Exception e) {
        // In case of any unforeseen error, wrap and rethrow as a runtime exception.
        throw new RuntimeException("Error computing diff structure for table: " + tableName, e);
    }
}

