public static void createConfigurationDirectory() {
    try {
        String osName = System.getProperty("os.name");
        String home = System.getProperty("user.home");
        String dirPath;

        if (osName != null && osName.toLowerCase().contains("windows")
                && osName.toLowerCase().contains("2000")) {
            // On Windows 2000, create lf5 in the Documents and Settings directory
            dirPath = home + File.separator + "lf5";
        } else {
            // On all other platforms, use the user.home directory
            dirPath = home + File.separator + "lf5";
        }

        File configDir = new File(dirPath);
        if (!configDir.exists()) {
            if (!configDir.mkdirs()) {
                System.err.println("Failed to create configuration directory: " + dirPath);
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
}

