public boolean equals(final byte[] data,int offset,final int len){
    if (data == null) {
        throw new NullPointerException("data");
    }
    if (offset < 0 || len < 0 || offset + len > data.length) {
        throw new IndexOutOfBoundsException("offset + len out of bounds: offset=" + offset + ", len=" + len + ", data.length=" + data.length);
    }
    byte[] internal = this.array;  // internal array field
    if (internal == null) {
        return len == 0;
    }
    if (internal.length != len) {
        return false;
    }
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

