public synchronized void send(final String message){
    if (message == null) {
        return;
    }
    String telnetMessage = message + "\r\n";
    if (clientWriters == null || clientWriters.isEmpty()) {
        return;
    }
    Iterator<PrintWriter> it = clientWriters.iterator();
    while (it.hasNext()) {
        PrintWriter out = it.next();
        if (out == null) {
            continue;
        }
        try {
            out.print(telnetMessage);
            out.flush();
        } catch (Exception e) {
            // Remove problematic writer to avoid future errors
            it.remove();
        }
    }
}

