protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input parameters
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value");
    }
    // If there is no duration, return an empty list
    if (start == end) {
        return new ArrayList<>();
    }

    List<TimeRange> ranges = new ArrayList<>();
    long nextStart = start;

    while (nextStart < end) {
        long nextEnd;
        // Prevent overflow when adding FETCH_DATA_DURATION
        if (nextStart > Long.MAX_VALUE - FETCH_DATA_DURATION) {
