static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    // Parse year, month, day from yyyymmdd format
    int year  = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day   = (int)(timeBucket % 100);
    // Basic date validation
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }
    // Compute bucket start day
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    // Reconstruct compressed time bucket
    return year * 10000L + month * 100L + bucketStartDay;
}

