    if (path.startsWith("/")) {
        start = 1;
    }
    String remaining = path.substring(start);
    if (remaining.isEmpty()) {
        return segments;
    }
    String[] parts = remaining.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue; // skip redundant slashes
        }
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (IllegalArgumentException | java.io.UnsupportedEncodingException e) {
                // If decoding fails, keep the original encoded segment
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

