    char first = Character.toUpperCase(name.charAt(0));
    if (name.length() == 1) {
        return String.valueOf(first);
    }
    return first + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("DataOutput cannot be null");
    }
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        // Write the bytes currently stored in the buffer node.
        // current.bytes is expected to be a byte array and current.limit denotes the bytes to write.
        out.write(current.bytes, 0, current.limit);
        totalSize += current.limit;
        current = current.next;
    }
    return totalSize;
}

