public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    // Use a ByteArrayOutputStream to read all bytes from the InputStream
    java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
    byte[] temp = new byte[8192];
    int read;
    while ((read = in.read(temp)) != -1) {
        baos.write(temp, 0, read);
    }
    byte[] data = baos.toByteArray();
    // Assume ClassFileBuffer has a field named `buffer` to hold the byte array
    // and a field named `pos` (or similar) that points to the current read position.
    // Clear any existing content and set the pointer to the start.
    try {
        java.lang.reflect.Field bufferField = this.getClass().getDeclaredField("buffer");
        bufferField.setAccessible(true);
        bufferField.set(this, data);
        java.lang.reflect.Field posField = this.getClass().getDeclaredField("pos");
        posField.setAccessible(true);
        posField.setInt(this, 0);
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // Fallback: if the fields don't exist by these names, throw an informative error
        throw new IOException("ClassFileBuffer does not expose expected fields 'buffer' and 'pos'; cannot load data", e);
    }
}

