private String escapeJson(String s) {
    StringBuilder out = new StringBuilder();
    for (char c : s.toCharArray()) {
        switch (c) {
            case '\"': out.append("\\\""); break;
            case '\\': out.append("\\\\"); break;
            case '\b': out.append("\\b"); break;
            case '\f': out.append("\\f"); break;
            case '\n': out.append("\\n"); break;
            case '\r': out.append("\\r"); break;
            case '\t': out.append("\\t"); break;
            default:
                if (c < 0x20 || c > 0x7e) {
                    out.append(String.format("\\u%04x", (int) c));
                } else {
                    out.append(c);
                }
        }
    }
    return out.toString();
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }
    if (!(Character.class.isAssignableFrom(type) || type == char.class)) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException(
                "Cannot convert String of length " + str.length() + " to a Character");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= Character.MIN_VALUE && intVal <= Character.MAX_VALUE) {
            return (char) intVal;
        } else {
            throw new IllegalArgumentException(
                "Number value " + intVal + " is outside the valid Character range");
        }
    }
    // Fallback: try to convert via toString
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to Character");
}

