public static Object findFirstMatch(Collection source, Collection candidates) {
    // Handle null arguments
    if (source == null || candidates == null) {
        return null;
    }
    // Iterate over each candidate and return the first that exists in source
    for (Object candidate : candidates) {
        try {
            if (source.contains(candidate)) {
                return candidate;
            }
        } catch (RuntimeException e) {
            // If source.contains throws a runtime exception, skip this candidate and continue
            continue;
        }
    }
    // No match found
    return null;
}

public static String trimTrailingWhitespace(String str){
    // Handle null input gracefully
    if (str == null) {
        return null;
    }
    int end = str.length() - 1;
    // Scan backwards to find the last non-whitespace character
    while (end >= 0 && Character.isWhitespace(str.charAt(end))) {
        end--;
    }
    // end now points to the last non-whitespace character, or -1 if all are whitespace
    return str.substring(0, end + 1);
}

