public final byte[] toByteArray(){
    try {
        if (buffers == null || buffers.isEmpty()) {
            return new byte[0];
        }
        int totalSize = 0;
        for (byte[] buf : buffers) {
            if (buf != null) {
                totalSize += buf.length;
            }
        }
        byte[] combined = new byte[totalSize];
        int offset = 0;
        for (byte[] buf : buffers) {
            if (buf != null && buf.length > 0) {
                System.arraycopy(buf, 0, combined, offset, buf.length);
                offset += buf.length;
            }
        }
        return combined;
    } catch (Exception e) {
        // Return an empty array on error
        return new byte[0];
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int len = str.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i += 2;
                    break;
                case 't':
                    sb.append('\t');
                    i += 2;
                    break;
                case 'n':
                    sb.append('\n');
                    i += 2;
                    break;
                case 'f':
                    sb.append('\f');
                    i += 2;
                    break;
                case 'r':
                    sb.append('\r');
                    i += 2;
                    break;
                case '\\':
                    sb.append('\\');
                    i += 2;
                    break;
                case '\"':
                    sb.append('\"');
                    i += 2;
                    break;
                case '\'':
                    sb.append('\'');
                    i += 2;
                    break;
                case 'u':
                    if (i + 6 <= len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 6;
                        } catch (NumberFormatException e) {
                            sb.append('\\').append('u');
                            i += 2;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i += 2;
                    }
                    break;
                default:
                    sb.append('\\').append(next);
                    i += 2;
                    break;
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

