private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // If the array is null, create a new array of length 1 of the specified component type.
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Both array and newArrayComponentType cannot be null.");
        }
        try {
            return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create new array of type " + newArrayComponentType, e);
        }
    }

    // Ensure the provided object is actually an array.
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array.");
    }

    int length = java.lang.reflect.Array.getLength(array);
    Class<?> componentType = arrayClass.getComponentType();

    try {
        Object newArray = java.lang.reflect.Array.newInstance(componentType, length + 1);
        System.arraycopy(array, 0, newArray, 0, length);
        return newArray;
    } catch (Exception e) {
        throw new RuntimeException("Failed to copy and grow array.", e);
    }
}

