private JsonObject convertProperties(List<KeyStringValuePair> properties){
    JsonObject json = new JsonObject();
    if (properties == null){
        return json;
    }
    for (KeyStringValuePair kv : properties){
        if (kv == null){
            continue;
        }
        try{
            String key   = kv.getKey();
            String value = kv.getValue();
            if (key == null){
                continue;
            }
            if (value == null){
                // skip null values to keep JSON compact
                continue;
            }
            json.addProperty(key, value);
        }catch (Exception e){
            // ignore individual invalid entries but keep processing others
            continue;
        }
    }
    return json;
}

protected int removeUnusedNodes() {
    int removedCount = 0;
    if (root == null) {
        return 0;
    }
    java.util.Queue<CategoryNode> queue = new java.util.LinkedList<>();
    queue.add(root);
    while (!queue.isEmpty()) {
        CategoryNode current = queue.poll();
        if (!current.isActive()) {
            CategoryNode parent = current.getParent();
            if (parent != null) {
                parent.getChildren().remove(current);
            } else { // current is root
                root = null;
            }
            removedCount++;
            continue; // skip its children
        }
        java.util.List<CategoryNode> children = current.getChildren();
        if (children != null) {
            for (CategoryNode child : children) {
                queue.add(child);
            }
        }
    }
    return removedCount;
}

