public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate parameters
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset is out of bounds");
        }
        if (byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteLength goes beyond the end of byteArrayValue");
        }
    } else if (byteLength > 0) {
        // When byteArrayValue is null, we simply insert zero bytes; no bounds check needed
    }

    // Ensure there is enough room in the payload array
    int requiredCapacity = this.length + byteLength;
    if (requiredCapacity > payload.length) {
        int newCapacity = Math.max(payload.length * 2, requiredCapacity);
        if (newCapacity < 0) { // overflow guard
            newCapacity = requiredCapacity;
        }
        byte[] newPayload = new byte[newCapacity];
        // Copy existing data to the new array
        System.arraycopy(payload, offset, newPayload, 0, length);
        payload = newPayload;
        offset = 0;
    }

    // Copy the bytes (or leave zeros for null byteArrayValue)
    if (byteLength > 0) {
        if (byteArrayValue != null) {
            System.arraycopy(byteArrayValue, byteOffset, payload, offset + length, byteLength);
        }
        // If byteArrayValue is null, the new region is already zeroed by the array creation
    }

    // Update the length field
    length += byteLength;
    return this;
}

