@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    try {
        AtmosphereResource.TRANSPORT transport = r.getTransport();
        if (transport == null) {
            return Action.CONTINUE;
        }
        // WebSocket connections are long‑lived; no suspension needed.
        if (transport == AtmosphereResource.TRANSPORT.WEBSOCKET) {
            return Action.CONTINUE;
        }
        // For any other transport we want the resource to be suspended
        // to keep the connection open for push.
        if (!r.isSuspended()) {
            r.suspend();
        }
    } catch (Exception e) {
        // Swallow any exception – the continuation of the pipeline
        // is not critical for these optional suspensions.
    }
    return Action.CONTINUE;
}

public double vertexWeight(Set<V> v){
    // Ensure the graph's adjacency structure is available
    if (adjacency == null) {
        throw new IllegalStateException("Adjacency map has not been initialized.");
    }
    // Validate input set
    if (v == null) {
        throw new IllegalArgumentException("Vertex set cannot be null.");
    }
    if (v.isEmpty()) {
        return 0.0;
    }
    double sum = 0.0;
    // Iterate over all source vertices
    for (Map.Entry<V, Map<V, Double>> sourceEntry : adjacency.entrySet()) {
        Map<V, Double> outEdges = sourceEntry.getValue();
        if (outEdges == null) continue;
        // For each target vertex in the source's outgoing edges,
        // add the weight if the target is in the given set.
        for (Map.Entry<V, Double> targetEntry : outEdges.entrySet()) {
            V target = targetEntry.getKey();
            if (v.contains(target)) {
                Double weight = targetEntry.getValue();
                if (weight != null) {
                    sum += weight;
                }
            }
        }
    }
    return sum;
}

