private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate parameters
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel must not be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException(
            "minLabel (" + minLabel + ") is out of bounds for bucketsByLabel size " + bucketsByLabel.size());
    }

    // Ensure bucket 0 exists
    Set<Integer> bucket0 = bucketsByLabel.get(0);
    if (bucket0 == null) {
        bucket0 = new HashSet<>();
        bucketsByLabel.set(0, bucket0);
    }

    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    if (sourceBucket == null || sourceBucket.isEmpty()) {
        // Nothing to move; make sure bucket is an empty set (not null)
        if (sourceBucket == null) {
            bucketsByLabel.set(minLabel, new HashSet<>());
        }
        return;
    }

    // Move vertices from sourceBucket to bucket0 and update their labels
    for (Integer vertex : new HashSet<>(sourceBucket)) { // copy to avoid concurrent modification
        if (vertex == null || vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException(
                "Vertex index out of bounds: " + vertex + " (labels size: " + labels.size() + ")");
        }
        // Update label
        labels.set(vertex, 0);
        // Move vertex to bucket0
        bucket0.add(vertex);
    }

    // Clear the source bucket
    sourceBucket.clear();
}

