    // If the original array is null, create a new array of length 1 and put the string in it.
    if (array == null) {
        String[] result = new String[1];
        result[0] = str; // str may be null, that's acceptable
        return result;
    }

    // Create a new array that can hold all existing elements plus one new entry
    String[] result = new String[array.length + 1];
    // Copy existing elements
    for (int i = 0; i < array.length; i++) {
        result[i] = array[i];
    }
    // Append the new string
    result[array.length] = str; // str may be null
    return result;
}

public static int countOccurrencesOf(String str, String sub) {
    // Handle null inputs as specified
    if (str == null || sub == null) {
        return 0;
    }

    // Avoid infinite loop: an empty substring would match at every position.
    // We choose to return 0 for an empty pattern (common defensive choice).
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index += sub.length(); // Move past the last matched occurrence
    }
    return count;
}

