/**
 * Pops the given number of abstract types from the output frame stack.
 * @param elements the number of abstract types that must be popped.
 */
private void pop(final int elements) {
    if (elements < 0) {
        throw new IllegalArgumentException("elements must be non‑negative: " + elements);
    }
    // Ensure there are enough elements on the stack to pop
    if (elements > outputStack.size()) {
        throw new IllegalStateException(
            "Cannot pop " + elements + " elements; only " + outputStack.size() + " present on the output stack");
    }
    // Remove the requested number of elements from the end of the stack
    for (int i = 0; i < elements; ++i) {
        outputStack.remove(outputStack.size() - 1);
    }
}

