private String parseToken(final char[] terminators) {
    // Basic validation
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array must not be null");
    }
    if (source == null) {
        return ""; // nothing to parse
    }

    StringBuilder sb = new StringBuilder();

    // If no terminators were supplied, consume the rest of the source
    if (terminators.length == 0) {
        while (pos < source.length()) {
            sb.append(source.charAt(pos));
            pos++;
        }
        return sb.toString();
    }

    // Consume characters until a terminator or end of source is reached
    while (pos < source.length()) {
        char current = source.charAt(pos);
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break; // Do not consume the terminator; leave it for subsequent parsing
        }
        sb.append(current);
        pos++;
    }

    return sb.toString();
}

