private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Handle null or empty input gracefully
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(Collections.emptyList(), 0L);
    }
    int n = bounds.size();
    long totalSum = 0L;
    int[] suffixInts = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            // Treat null as zero or skip depending on requirements.
            // Here we choose to treat as zero to avoid NPE.
            val = 0;
        }
        totalSum += val;
        // Casting to int might truncate if overflow, but interface expects Integer list.
        suffixInts[i] = (int) totalSum;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int val : suffixInts) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array cannot be null");
    }
    int len = arr.length;
    if (from < 0 || to >= len || from > to) {
        throw new IllegalArgumentException("Invalid range: from=" + from + ", to=" + to + ", array length=" + len);
    }
    int i = from;
    int j = to;
    while (i < j) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
        j--;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    // Iterate over the source list's nodes using its sentinel nodes
    ListNode<E> node = list.head.next;
    while (node != list.tail) {
        // Keep reference to the next node before moving `node`
        ListNode<E> nextNode = node.next;
        // Remove 'node' from the source list
        list.removeListNode(node);
        // Add 'node' to the current list
        this.addListNode(node);
        // Advance to the next node in the original list
        node = nextNode;
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // Both null => true
    if (str == null && prefix == null) {
        return true;
    }
    // One null => false
    if (str == null || prefix == null) {
        return false;
    }
    int prefixLen = prefix.length();
    // Empty prefix always matches
    if (prefixLen == 0) {
        return true;
    }
    // Prefix longer than string cannot match
    if (prefixLen > str.length()) {
        return false;
    }
    if (ignoreCase) {
        // regionMatches with ignoreCase flag
        return str.regionMatches(true, 0, prefix, 0, prefixLen);
    } else {
        return str.startsWith(prefix);
    }
}

