public void abbreviate(final int nameStart, final StringBuffer buf){
    // Safely abbreviate a name starting at 'nameStart' and append the abbreviation to 'buf'.
    // Assumes the class has a field named 'name' of type String.
    // The abbreviation consists of the initial letters (capitalized) of each word in the
    // remaining substring, words being sequences of alphabetic characters separated by
    // non-alphabetic characters.
    if (buf == null)   // nothing to append to
        return;
    try {
        if (name == null || name.isEmpty())
            return;
        int length = name.length();
        if (nameStart < 0)      // normalize negative indices
            nameStart = 0;
        if (nameStart >= length) // nothing to abbreviate
            return;
        String remainder = name.substring(nameStart);
        if (remainder.isEmpty())
            return;
        String[] parts = remainder.split("[^A-Za-z]+");
        for (String part : parts) {
            if (part.isEmpty())
                continue;
            char initial = Character.toUpperCase(part.charAt(0));
            buf.append(initial);
        }
    } catch (Exception e) {
        // Silently ignore any unexpected errors to preserve caller’s logic flow.
    }
}

