private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new NullPointerException("Graph and vertices must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < size; i++) {
        V u = (V) arr[i];
        for (int j = i + 1; j < size; j++) {
            V v = (V) arr[j];
            if (!graph.containsEdge(u, v) && !graph.containsEdge(v, u)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    for (K key : keys) {
        if (key == null) {
            bounds.add(null);
            continue;
        }
        if (!(key instanceof Comparable)) {
            throw new IllegalArgumentException("Key objects must implement Comparable");
        }
        @SuppressWarnings("unchecked")
        Comparable<K> compKey = (Comparable<K>) key;

        Integer maxLower = null;
        for (K other : keys) {
            if (other == null || other == key) continue;
            if (!(other instanceof Comparable)) continue;
            @SuppressWarnings("unchecked")
            Comparable<K> compOther = (Comparable<K>) other;

            if (compOther.compareTo(key) < 0) {
                Integer val;
                if (other instanceof Integer) {
                    val = (Integer) other;
                } else {
                    continue; // can't convert non‑Integer to Integer for return
                }
                if (maxLower == null || val > maxLower) {
                    maxLower = val;
                }
            }
        }
        bounds.add(maxLower);
    }
    return bounds;
}

