        }
        if (idx >= descriptor.length() || descriptor.charAt(idx) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        // Return type is ignored
    } else {
        // Single field type descriptor
        consumeAndPopType(descriptor, 0);
    }
}

private int consumeAndPopType(String desc, int index){
    int nextIndex = skipType(desc, index);
    int size = typeSize(desc, index);
    for (int i = 0; i < size; i++) {
        if (outputFrameStack.isEmpty()) {
            throw new RuntimeException("Output frame stack underflow");
        }
        outputFrameStack.pop();
    }
    return nextIndex;
}

private int skipType(String desc, int index){
    if (index >= desc.length()) {
        throw new IllegalArgumentException("Descriptor too short");
    }
    char c = desc.charAt(index);
    switch (c) {
        case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
            return index + 1;
        case 'L':
            int semi = desc.indexOf(';', index);
            if (semi == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            return semi + 1;
        case '[':
            int i = index + 1;
            while (i < desc.length() && desc.charAt(i) == '[') {
                i++;
            }
            return skipType(desc, i);
        default:
            throw new IllegalArgumentException("Unknown type descriptor: " + c);
    }
}

private int typeSize(String desc, int index){
    char c = desc.charAt(index);
    return (c == 'J' || c == 'D') ? 2 : 1;
}

