private List<Integer> computeUpperBounds(List<K> keys){
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int bound = 0;
        try {
            if (key != null && key instanceof Number) {
                bound = ((Number) key).intValue() + 1;
            }
        } catch (Exception ex) {
            // In case of unexpected conversion issues, keep bound as 0
        }
        result.add(bound);
    }
    return result;
}

