public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        return null;
    }

    // Trim any surrounding whitespace
    path = path.trim();
    relativePath = relativePath.trim();

    // If relativePath is empty or just ".", return the original path (or adjustment for trailing slash)
    if (relativePath.isEmpty() || ".".equals(relativePath)) {
        return path;
    }

    // Determine the base directory from the given full path.
    // If path ends with '/', treat it as a directory; otherwise, consider the part before the last '/'.
    String baseDir;
    if (path.endsWith("/")) {
        baseDir = path;
    } else {
        int lastSlash = path.lastIndexOf('/');
        if (lastSlash < 0) {
            baseDir = "";
        } else {
            baseDir = path.substring(0, lastSlash + 1); // keep the slash for easy concatenation
        }
    }

    // Split the relative path into components
    String[] relParts = relativePath.split("/+");
    // Use a dynamic array (stack) to resolve '..' and '.' components
    java.util.ArrayDeque<String> stack = new java.util.ArrayDeque<>();

    for (String part : relParts) {
        if (part.isEmpty() || ".".equals(part)) {
            // Skip these parts
            continue;
        } else if ("..".equals(part)) {
            if (!stack.isEmpty()) {
                stack.pop();
            } else {
                // If stack is empty and we encounter '..', we cannot go up further.
                // In a typical file system, this would remain at the root.
                // We simply ignore further '..' components to avoid invalid paths.
                // Alternatively, one could keep an explicit ".." component,
                // but for simplicity we ignore it.
            }
        } else {
            stack.push(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();

    // If baseDir got trimmed to empty string (relative file path) and we have stack components, we
    // start with an empty base; otherwise, use baseDir as the starting point.
    if (!baseDir.isEmpty()) {
        result.append(baseDir);
    }

    // Because we used a stack (LIFO), we need to reverse the order
    java.util.Iterator<String> it = stack.descendingIterator();
    while (it.hasNext()) {
        if (result.length() != 0 && result.charAt(result.length() - 1) != '/') {
            result.append('/');
        }
        result.append(it.next());
    }

    // If the result is still empty, it means the relative path resolved to the current directory.
    if (result.length() == 0) {
        result.append(".");
    }

    return result.toString();
}

