static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return new String[0];
    }
    int nullCount = 0;
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        // All elements are non-null, cast to String[] if possible
        if (array instanceof String[]) {
            return (String[]) array;
        }
        // Fallback: create and copy
        String[] produced = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            produced[i] = (String) array[i];
        }
        return produced;
    }
    String[] result = new String[array.length - nullCount];
    int pos = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[pos++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the position of the last '.' in the filename
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1; // No extension separator
    }

    // Determine the index of the last file separator ('/' or '\\')
    int slashIndex = filename.lastIndexOf('/');
    int backslashIndex = filename.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(slashIndex, backslashIndex);

    // If the dot occurs after the last separator, it's an extension
    return (dotIndex > lastSeparatorIndex) ? dotIndex : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold){
    try {
        if (timestamp < 0 || expiredThreshold < 0) {
            throw new IllegalArgumentException("Timestamp and expiredThreshold must be non-negative");
        }
        long now = System.currentTimeMillis();
        return (now - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of any unexpected error, consider the metric expired to avoid stale data
        return true;
    }
}

Edge edgeToNext(){
    // Ensure the iterator that provides nodes has been initialized
    if (nodeIterator == null) {
        throw new IllegalStateException("Node iterator has not been initialized.");
    }

    // Attempt to fetch the next node; throw if none available
    Node nextNode;
    try {
        nextNode = nodeIterator.next();
    } catch (NoSuchElementException e) {
        throw new NoSuchElementException("No next node available for edge construction.");
    }

    // On the very first call there is no previous node, so no edge can be formed yet.
    if (previousNode == null) {
        previousNode = nextNode;
        return null;
    }

    // Resolve real counterparts if either node is virtual
    Node start = previousNode.isVirtual() ? previousNode.getRealNode() : previousNode;
    Node end   = nextNode.isVirtual()    ? nextNode.getRealNode() : nextNode;

    if (start == null || end == null) {
        throw new IllegalArgumentException("Encountered null node during edge creation.");
    }

    // Create the edge and update state for the next call
    Edge edge = new Edge(start, end);
    previousNode = nextNode;
    return edge;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    try {
        if (str == null || substring == null) {
            return false;
        }
        int subLen = substring.length();
        int strLen = str.length();
        if (subLen == 0) {
            // An empty substring is considered to match at any index within bounds
            return index >= 0 && index <= strLen;
        }
        if (index < 0 || index > strLen - subLen) {
            return false;
        }
        for (int i = 0; i < subLen; i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        // If any unexpected exception occurs, return false rather than propagating it
        return false;
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }

    // Safely get the rendered message from the LoggingEvent
    String message;
    try {
        // Try the most common method first
        message = event.getRenderedMessage();
    } catch (NoSuchMethodError | IllegalAccessError e) {
        // Fall back if method isn't available
        message = event.getMessage() != null ? event.getMessage().toString() : "";
    }

    if (message == null) {
        message = "";
    }

    // Assume there is a field called `clientWriters` storing the connected client writers
    // It should be a thread-safe list or accessed via synchronization
    if (clientWriters == null) {
        return;
    }

    synchronized (clientWriters) {
        // We use an iterator so we can safely remove broken writers during iteration
        var iterator = clientWriters.iterator();
        while (iterator.hasNext()) {
            var writer = iterator.next();
            try {
                writer.println(message);
                writer.flush();
            } catch (Exception exc) {
                // If writing fails, assume the client has disconnected and remove it
                iterator.remove();
            }
        }
    }
}

