    return String.valueOf(ch).intern();
}

private void checkIfPackedField() throws IOException {
    try {
        // The field is considered packed if its wire type is LENGTH_DELIMITED (wire type 2).
        int wireType = this.tag & 0x7;
        if (wireType == 2) {
            // Update internal state to indicate that packed fields are being read.
            this.isPackedField = true;
        }
    } catch (Exception e) {
        throw new IOException("Error while checking packed field", e);
    }
}

public int readTag() throws IOException {
    int shift = 0;
    int result = 0;
    while (shift < 32) {
        int b = in.read();          // read next byte from the underlying stream
        if (b == -1) {              // EOF reached before a tag could be fully read
            return 0;               // zero signals end of message
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {      // finished reading the varint
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed tag: too many bytes");
}

final ByteVector put11(final int byteValue1, final int byteValue2){
    int required = size + 2;
    if (required > bytes.length) {
        int newCap = Math.max(bytes.length << 1, required);
        byte[] newBytes = new byte[newCap];
        System.arraycopy(bytes, 0, newBytes, 0, size);
        bytes = newBytes;
    }
    bytes[size++] = (byte) byteValue1;
    bytes[size++] = (byte) byteValue2;
    return this;
}

private String buildContentRange() {
    try {
        java.lang.reflect.Field startField = this.getClass().getDeclaredField("start");
        java.lang.reflect.Field endField = this.getClass().getDeclaredField("end");
        java.lang.reflect.Field totalField = this.getClass().getDeclaredField("totalSize");
        startField.setAccessible(true);
        endField.setAccessible(true);
        totalField.setAccessible(true);
        Object startObj = startField.get(this);
        Object endObj = endField.get(this);
        Object totalObj = totalField.get(this);
        String start = startObj != null ? startObj.toString() : "0";
        String end = endObj != null ? endObj.toString() : "0";
        String total = totalObj != null ? totalObj.toString() : "*";
        return "bytes " + start + "-" + end + "/" + total;
    } catch (Exception e) {
        return null;
    }
}

import java.io.*;
import java.util.*;

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(file), "UTF-8"))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Skip empty or whitespace-only lines
            if (line.trim().isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static factory method `fromString`
                snapshot = ThreadSnapshot.fromString(line);
            } catch (Exception e) {
                // If parsing fails, skip this line
                continue;
            }
            if (snapshot == null) {
                continue;
            }
            long ts = snapshot.getTimestamp(); // Assume method returns a long timestamp
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStart(); // Assume getters exist
                long end = range.getEnd();
                if (ts >= start && ts <= end) {
                    result.add(snapshot);
                    break; // No need to check other ranges
                }
            }
        }
    } catch (IOException io) {
        // Propagate the IOException as required by signature
        throw io;
    }
    return result;
}
